import logging
import os
import posixpath

from ..command import CommandBuilder

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class RacclimxCommand(CommandBuilder):
    def __init__(self, options, verbose=True):
        flags = ['-v'] if verbose else []
        super().__init__(executable='racclimx.sh', flags=flags, options=options)


class Racclimx:
    EXPORT_DIR = '/var/opt/oss/global/racops/export/'
    IMPORT_DIR = '/var/opt/oss/global/racops/import/'

    def __init__(self, ssh_cmwas_node):
        self.ssh_cmwas_node = ssh_cmwas_node

    def _execute_operation(self, parameters, verbose=True, ignore_errors=False, timeout=7200):
        command = RacclimxCommand(parameters, verbose).text
        with self.ssh_cmwas_node as ssh:
            logger.info(f'Executing command: {command}')
            stdout = ssh.execute_command(
                command,
                ignore_stderr=ignore_errors,
                ignore_rc=ignore_errors,
                timeout=timeout
            ).stdout
        return stdout

    def _put_file(self, file_name, local_dir, remote_dir, timeout=90):
        with self.ssh_cmwas_node as ssh:
            local_file_path = os.path.join(local_dir, file_name)
            remote_file_path = posixpath.join(remote_dir, file_name)
            ssh.put_file(local_file_path, remote_file_path, timeout)
            logger.info(f'File uploaded to NetAct under {remote_file_path}')

    def _get_file(self, file_name, remote_dir, local_dir, timeout=90):
        with self.ssh_cmwas_node as ssh:
            remote_file_path = posixpath.join(remote_dir, file_name)
            local_file_path = os.path.join(local_dir, file_name)
            if not os.path.isdir(local_dir):
                os.makedirs(local_dir)
            ssh.get_file(remote_file_path, local_file_path, timeout)
            logger.info(f'File downloaded to local machine under {local_file_path}')

    def _remove_remote_file(self, file_name, remote_dir, timeout=90):
        with self.ssh_cmwas_node as ssh:
            remote_file_path = posixpath.join(remote_dir, file_name)
            ssh.execute_command(f'rm -f "{remote_file_path}"', timeout=timeout)

    def _put_file_and_execute_operation(self, parameters, file_name, local_dir=None, remote_dir=None,
                                        cleanup=True, verbose=True, ignore_errors=False, timeout=7200):
        schedule = parameters.get('-schedule')
        with self.ssh_cmwas_node:
            try:
                if file_name and local_dir and remote_dir:
                    self._put_file(file_name, local_dir, remote_dir, timeout)
                return self._execute_operation(
                    parameters, verbose=verbose, ignore_errors=ignore_errors, timeout=timeout)
            finally:
                if cleanup and file_name and local_dir and remote_dir and not schedule:
                    self._remove_remote_file(file_name, remote_dir, timeout)

    def _execute_operation_and_get_file(self, parameters, file_name, remote_dir=None, local_dir=None,
                                        cleanup=True, verbose=True, ignore_errors=False, timeout=7200):
        schedule = parameters.get('-schedule')
        with self.ssh_cmwas_node:
            stdout = self._execute_operation(
                parameters, verbose=verbose, ignore_errors=ignore_errors, timeout=timeout)
            if file_name and local_dir and remote_dir and not schedule:
                self._get_file(file_name, remote_dir, local_dir, timeout)
                if cleanup:
                    self._remove_remote_file(file_name, remote_dir, timeout)
        return stdout
